import re

def roman_to_int(s: str) -> int:
    pattern = (
        r'^M{0,3}'
        r'(CM|CD|D?C{0,3})'
        r'(XC|XL|L?X{0,3})'
        r'(IX|IV|V?I{0,3})$'
    )
    if not s or not re.match(pattern, s):
        raise ValueError(f"Invalid Roman numeral: {s}")

    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        val = values[ch]
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total
